import json
got = json.load(open('out.json'))
exp = json.load(open('/workspace/examples/diamond.expected.json'))

def canon(got, exp, path=""):
    # compare with tolerance for witness choice ambiguity
    problems = []
    if type(got) != type(exp):
        if isinstance(exp, dict) and isinstance(got, dict):
            pass
        else:
            return [f"{path}: type {type(got)} vs {type(exp)}"]
    if isinstance(exp, dict):
        if set(got) != set(exp):
            problems.append(f"{path}: keys {sorted(set(got)^set(exp))}")
        for k in exp:
            if k in got:
                problems += canon(got[k], exp[k], path+"/"+k)
    elif isinstance(exp, list):
        if len(got) != len(exp):
            problems.append(f"{path}: len {len(got)} vs {len(exp)}")
        else:
            for i,(a,b) in enumerate(zip(got,exp)):
                problems += canon(a,b,f"{path}[{i}]")
    else:
        if got != exp:
            problems.append(f"{path}: {got!r} != {exp!r}")
    return problems

# witnesses: candidate order/choice is free; compare as sets of tuples
for c_got, c_exp in zip(got["classes"], exp["classes"]):
    g_w = sorted(tuple(sorted(set(w))) for w in c_got["candidate_witnesses"])
    g_set = {tuple(w) for w in c_got["candidate_witnesses"]}
    e_set = {tuple(w) for w in c_exp["candidate_witnesses"]}
    assert g_set == e_set, (c_got["candidate_witnesses"], c_exp["candidate_witnesses"])
    del c_got["candidate_witnesses"], c_exp["candidate_witnesses"]
    assert len(c_got["candidate_witnesses"] if "candidate_witnesses" in c_got else []) == 0

probs = canon(got, exp)
print("PROBLEMS:", probs if probs else "NONE - full match")
EOF
